    [637] = {
        en = "The Kaldorei and the Well of Eternity",
        title = "Калдорай і Криниця Вічності",
        pages = {
            [637] = [[За десять тисяч років до того, як орки й люди зійшлися в Першій війні, у світі Азероту був один велетенський материк, оточений безкраїми бурхливими морями. На цій землі, відомій як Калімдор, жили різні народи й створіння. Кожен боровся за виживання серед диких стихій світу наяву. У серці темного материка лежало загадкове озеро, що сяяло невідомою силою.]],
            [638] = [[Озеро, яке згодом назвали Криницею Вічності, було справжнім серцем магії та природної сили світу. Криниця черпала енергію з безмежної Великої Темряви поза світом і, мов таємниче джерело, розливала її по всьому світу, живлячи життя в усіх його дивовижних формах. Згодом до чарівних берегів озера обережно підійшло первісне плем’я нічних людиноподібних істот.]],
            [639] = [[Принаджені дивною силою Криниці, дикі кочовики звели грубі житла на її тихих берегах. З часом вселенська сила Криниці змінила плем’я. Вони стали сильними, мудрими й майже безсмертними. Плем’я взяло ім’я калдорай, що їхньою мовою означало «діти зірок». На честь свого молодого суспільства вони звели великі споруди й храми довкола озера.]],
            [640] = [[Калдорай, яких згодом назвали нічними ельфами, поклонялися богині місяця Елуні й вірили, що вдень вона спить у сяйливих глибинах Криниці. Перші жерці й провидці нічних ельфів із невситимою цікавістю досліджували Криницю, прагнучи осягнути її незвідані таємниці й силу. Коли їхнє суспільство зросло, нічні ельфи обійшли Калімдор у всіх напрямках і зустріли безліч його мешканців.]],
            [641] = [[Лише стародавні й могутні дракони змушували їх зупинитися й зважити на небезпеку. Хоч велетенські змієподібні звірі часто трималися осторонь, вони багато робили, щоб уберегти відомі землі від загроз. Нічні ельфи вважали, що дракони бачать себе охоронцями світу й що найкраще залишити їх та їхні таємниці в спокої.]],
            [642] = [[Згодом цікавість привела нічних ельфів до знайомства й дружби з кількома могутніми істотами. Серед них був Кенарій, могутній напівбог прадавніх лісів. Великодушний Кенарій полюбив допитливих нічних ельфів і довго навчав їх про світ природи. Мирні калдорай навчилися відчувати життя лісів Калімдору й тішилися природною рівновагою.]],
            [643] = [[Та за незліченні віки цивілізація нічних ельфів розрослася і землями, і культурою. Їхні храми, дороги й оселі простяглися по всьому темному материку. Азшара, вродлива й обдарована королева нічних ельфів, звела на березі Криниці величезний розкішний палац. У його оздоблених коштовностями залах жили її улюблені слуги.]],
            [644] = [[Слуги, яких вона звала квел'дорай, або високородними, догоджали кожній її примсі й вважали себе вищими за решту свого народу. Хоч усі однаково любили королеву Азшару, до високородних ображений люд таємно відчував ненависть. Розділяючи цікавість жерців до Криниці Вічності, Азшара наказала освіченим високородним дослідити її таємниці й з’ясувати її справжнє призначення у світі.]],
            [645] = [[Високородні поринули в роботу й без упину вивчали Криницю. З часом вони навчилися спрямовувати й підкоряти її вселенську силу. Їхні необачні досліди тривали, і вони з’ясували, що новим даром можуть за бажанням і творити, і руйнувати. Нерозважливі високородні натрапили на первісну магію й вирішили присвятити себе її опануванню.]],
            [646] = [[Азшара та її високородні погоджувалися, що магія небезпечна, якщо нею користуватися безвідповідально. Попри це вони чаклували без жодної обережності. Кенарій і чимало мудрих учених нічних ельфів попереджали, що ігри з таким непевним мистецтвом принесуть лише лихо. Та Азшара та її послідовники вперто нарощували свою нову силу.]],
            [647] = [[Що могутнішими ставали Азшара й високородні, то виразніше змінювалася їхня вдача. Гордовита, відлюдкувата знать дедалі жорстокіше й безжальніше ставилася до інших нічних ельфів. Похмура тінь огорнула колись чарівну вроду Азшари. Вона почала віддалятися від відданих підданих і вже не хотіла бачити нікого, крім довірених жерців-високородних.]],
            [648] = [[Молодий зухвалий учений Фуріон Шаленство Бурі, який багато часу присвятив вивченню впливу Криниці, почав підозрювати, що якась жахлива сила спотворює високородних і його любу королеву. Він ще не міг уявити зла, яке насувалося, та знав, що життя нічних ельфів невдовзі зміниться назавжди…]],
