        pages = {
            [1796] = [[Серед драконячих зграй п’ять панували над іншими. Саме їм титани доручили опікуватися молодим світом. Наймогутніші члени Пантеону наділили ватажків цих зграй часткою своєї сили. Цих величних драконів, перелічених нижче, стали звати Великими Аспектами, або Драконячими Аспектами.]],
            [1797] = [[Аман'Тул, Верховний Батько Пантеону, наділив велетенського бронзового дракона Ноздорму часткою своєї вселенської сили. Він доручив Ноздорму стерегти сам час і наглядати за вічно мінливими шляхами долі. Стриманий і шляхетний Ноздорму став відомим як Позачасовий.]],
            [1798] = [[Еонар, титанка й покровителька всього життя, передала частку сили величній червоній дракониці Алекстразі. Відтоді Алекстразу знали як Берегиню Життя. Вона піклувалася про всіх живих створінь світу. За найвищу мудрість і безмежне співчуття до всього живого її увінчали королевою драконів і дали владу над її народом.]],
            [1799] = [[Еонар також благословила молодшу сестру Алекстрази, гнучку зелену драконицю Ізеру, часткою сили природи. Ізера впала у вічне заціпеніння й пов’язала себе зі Сном Творіння. Відома як Сновидиця, вона наглядала за дикою природою молодого світу зі свого зеленого царства, Смарагдового Сну.]],
            [1800] = [[Норґаннон, титан-хранитель знань і великий маг, дарував синьому дракону Маліґосу частку своєї могутності. Відтоді Маліґоса звали Ткачем Заклинань, хранителем магії й потаємних арканічних знань.]],
            [1801] = [[Каз'ґорот, титан-творець і коваль світу, передав частку своєї могутності великому чорному дракону Нелтаріону. Великодушному Нелтаріону, якого згодом прозвали Стражем Землі, доручили панувати над землею й глибинами світу. Він уособлював силу самого світу й був наймогутнішим союзником Алекстрази.]],
            [1802] = [[Наділені силою, п’ять Аспектів мусили захищати світ, поки титани будуть відсутні. Дракони були готові берегти їхнє творіння, і титани назавжди покинули Азерот. На жаль, Сарґерас мав рано чи пізно довідатися про існування новонародженого світу…]],
        },
    },
    [1976] = {
        en = "The Alliance of Lordaeron",
        title = "Альянс Лордерона",
        catalog_pages = { [1976] = 1 },
        pages = {
            [1977] = [[Уперше за майже три тисячі років розрізнені держави Аратора знову об’єдналися під спільним стягом. Призначений верховним командувачем військ Альянсу, лорд Лотар підготував свої армії до приходу Орди.]],
            [1978] = [[За допомогою своїх лейтенантів, Утера Світлоносця, адмірала Деліна Праудмура й Тураліона, Лотар переконав у близькій загрозі й інші народи Лордерона. Альянс здобув підтримку стійких дворфів Залізогарта й невеликої кількості вищих ельфів Квел'Таласа.]],
            [1979] = [[Ельфів, якими тоді правив Анастеріан Сонячний Блукач, майбутня війна мало цікавила. Однак обов’язок велів їм допомогти Лотарові, останньому нащадку роду Араті, який допоміг ельфам у давнину.]],
            [1980] = [[Орда, яку тепер очолював воєвождь Молот Згуби, привела оґрів зі свого рідного Дренору й набрала у свої лави скривджених лісових тролів Амані. Рушивши у великий похід, щоб захопити дворфське королівство Каз-Модан і південь Лордерона, вона легко зламала увесь спротив.]],
            [1981] = [[Величезні битви Другої війни точилися і на морі, і в небі. Орда якимось чином відкопала могутню реліквію, відому як Душа Демона, й поневолила нею стародавню королеву драконів Алекстразу. Погрожуючи розбити її дорогоцінні яйця, Орда змусила Алекстразу послати на війну дорослих дітей. Шляхетних червоних драконів примусили битися за Орду, і вони билися.]],
            [1982] = [[Війна шаленіла по Каз-Модану, Лордерону й самому Азероту. Під час північного походу Орда спалила прикордоння Квел'Таласа, і цим остаточно схилила ельфів до підтримки Альянсу. Великі міста й містечка Лордерона були спалені й спустошені війною. Попри брак підмоги й значну перевагу ворогів, Лотар із союзниками стримав вороже військо.]],
            [1983] = [[Та в останні дні Другої війни, коли перемога Орди над Альянсом здавалася майже певною, між двома наймогутнішими орками Азероту спалахнула люта ворожнеча. Поки Молот Згуби готував останній штурм столиці Лордерона, який мав розчавити рештки Альянсу, Ґул'дан зі своїми послідовниками покинув пости й вийшов у море.]],
            [1984] = [[Приголомшений Молот Згуби втратив через зраду Ґул'дана майже половину свого війська. Йому довелося відступити й відмовитися від найкращого шансу перемогти Альянс.]],
            [1985] = [[Жадібний до влади Ґул'дан, одержимий мрією стати богом, вирушив на відчайдушні пошуки Гробниці Сарґераса під морем. Він вірив, що там приховано таємницю найвищої сили. Ґул'дан, який уже прирік своїх одноплемінників на рабство в Палаючого Легіону, не зважав на свої обов’язки перед Молотом Згуби.]],
            [1986] = [[За підтримки кланів Буревикрадачів і Молота Сутінків Ґул'дану вдалося підняти Гробницю Сарґераса з морського дна. Та коли він відчинив стародавнє затоплене сховище, на нього там чекали тільки збожеволілі демони.]],
            [1987] = [[Прагнучи покарати орків-відступників за їхню згубну зраду, Молот Згуби послав війська вбити Ґул'дана й повернути решту. За свою необачність Ґул'дан поплатився життям. Його розірвали збожеволілі демони, яких він сам випустив. Без ватажка відступницькі клани швидко впали перед розлюченими легіонами Молота Згуби.]],
            [1988] = [[Повстання придушили, та Орда не змогла надолужити страшних втрат. Зрада Ґул'дана дала Альянсові надію й час, щоб перегрупуватися й ударити у відповідь.]],
            [1989] = [[Побачивши, що Орда розпадається зсередини, лорд Лотар зібрав решту війська й відкинув Молота Згуби на південь, у зруйноване серце Штормовію. Там Альянс замкнув відступаючу Орду у вулканічній фортеці Чорноскельного шпиля. Лорд Лотар поліг у бою при підніжжі шпиля, та в останню мить його лейтенант Тураліон згуртував війська Альянсу й погнав Орду назад у бездонне болото Скорбот.]],
            [1990] = [[Війська Тураліона знищили Темний Портал, чарівну браму, яка сполучала орків із рідним Дренором. Відрізана від підкріплення й роздерта чварами, Орда зрештою зламалася й упала під натиском Альянсу.]],
            [1991] = [[Розпорошені орочі клани швидко зібрали й замкнули під вартою в ізоляційних таборах. Здавалося, Орда переможена назавжди, та дехто дуже сумнівався, що мир протримається. Кадґар, тепер уже уславлений архімаг, переконав верховне командування Альянсу звести фортецю Підсвітньої Варти. Вона мала наглядати за руїнами Темного Порталу й не допустити нових вторгнень із Дренору.]],
        },
    },
    [2018] = {
        en = "The Battle of Grim Batol",
        title = "Битва за Ґрім-Батол",
        pages = {
            [2018] = [[Тим часом на зруйнованих війною південних землях розпорошені рештки Орди билися за виживання. Ґром Пеклокрик і його клан Пісні Війни уникли полону, а Мертве Око та його клан Кривавої Очниці схопили й замкнули в лордеронських ізоляційних таборах. Повстання полонених коштували дорого, та наглядачі невдовзі знову підкорили своїх лютих підопічних.]],
            [2019] = [[Альянс не знав, що великий загін орків досі вільно блукає північними пустками Каз-Модана. Клан Драконової Пащі, який очолював сумнозвісний чорнокнижник Некрос, користувався стародавньою Душею Демона, щоб керувати королевою драконів Алекстразою та її зграєю. Тримаючи королеву в заручницях, Некрос зібрав таємне військо в покинутій, а за чутками й проклятій твердині Дикого Молота, Ґрім-Батолі.]],
            [2020] = [[Некрос збирався кинути свої війська й могутніх червоних драконів проти Альянсу. Він сподівався знову об’єднати Орду й продовжити завоювання Азероту. Задум не здійснився. Невеликий загін спротиву на чолі з магом-людиною Роніном знищив Душу Демона й звільнив королеву драконів від влади Некроса.]],
            [2021] = [[У люті дракони Алекстрази рознесли Ґрім-Батол і спалили більшу частину клану Драконової Пащі. Великі плани Некроса на об’єднання пішли прахом, коли військо Альянсу схопило решту вцілілих орків і кинуло до ізоляційних таборів. Поразка клану Драконової Пащі поклала край Орді й шаленій жазі крові орків.]],
        },
    },
    [2101] = {
        en = "The Lich King Triumphant",
        title = "Тріумф Короля-Ліча",
        pages = {
            [2101] = [[Навіть ослаблений Артас зрештою перехитрив Іллідана й першим дістався до Зледенілого трону. Рунним клинком Кригожурбою він розбив крижану в’язницю Короля-Ліча й вивільнив зачаровані шолом і нагрудник Нер'зула.]],
            [2102] = [[Артас надягнув шолом неймовірної сили й став новим Королем-Лічем. Духи Нер'зула й Артаса злилися в одну могутню істоту, як і замислював Нер'зул. Іллідан із військом мусив із ганьбою тікати назад у Позамежжя, а Артас став однією з наймогутніших істот, яких будь-коли знав світ.]],
            [2103] = [[Тепер Артас, новий безсмертний Король-Ліч, перебуває в Нортренді. За чутками, він відбудовує цитадель Крижаної Корони. Його довірений поплічник Кел'Тузад командує Скарою в Зачумлених землях. Сильвана та її бунтівні Відречені тримають лише Тірісфальське перелісся, малу частину розореного війною королівства.]],
        },
    },
    [1787] = {
        en = "The Old Gods and the Ordering of Azeroth",
        title = "Старі Боги та впорядкування Азероту",
        pages = {
            [1787] = [[Не знаючи, що Сарґерас надумав знищити всі їхні незліченні творіння, титани й далі мандрували зі світу у світ, надаючи кожній планеті форми й ладу на власний розсуд. Під час мандрів вони натрапили на малий світ, який його мешканці згодом назвуть Азеротом.]],
            [1788] = [[На первісній землі титани зустріли ворожих істот стихій. Ті поклонялися неосяжно лихим істотам, відомим тільки як Старі Боги. Елементалі заприсяглися відкинути титанів і вберегти свій світ від металевого дотику загарбників.]],
            [1789] = [[Занепокоєний лиходійством Старих Богів, Пантеон пішов війною на елементалів та їхніх темних панів. Війська Старих Богів очолили наймогутніші стихійні полководці: Раґнарос, володар вогню, Теразана, Кам’яна Мати, Ал'Акір, володар вітру, і Нептулон, Мисливець Припливів.]],
            [1790] = [[Стихійні війська шаленіли по всій землі та зійшлися з велетенськими титанами. Сила елементалів перевищувала розуміння смертних, але навіть разом вони не могли спинити могутніх титанів. Один по одному володарі стихій падали, і їхні війська розсіювалися.]],
            [1791] = [[Пантеон розбив твердині Старих Богів і закував п’ятьох лихих богів глибоко під землею. Коли їхня сила вже не могла втримати буйних духів у матеріальному світі, елементалів вигнали до виміру безодні, де вони мали вічно змагатися між собою. З їхнім відходом природа втихла й у світі запанував мирний лад. Упевнившись, що загрозу стримано, титани взялися до роботи.]],
            [1792] = [[Титани наділили кілька народів силою допомагати їм формувати світ. Щоб видовбати бездонні печери під землею, вони створили з чарівного живого каменю земельників, схожих на дворфів. Щоб поглибити моря й підняти суходіл із морського дна, вони створили величезних, але лагідних морських велетнів. Багато епох титани рухали й формували землю, аж доки не постав єдиний досконалий материк.]],
            [1793] = [[У центрі материка титани створили озеро мерехтливої енергії. Озеро, яке вони назвали Криницею Вічності, мало стати джерелом життя для всього світу. Його могутня сила мала живити кістяк світу й допомогти життю вкоренитися в родючій землі. З часом на первісному материку забуяли рослини й дерева та розплодилися чудовиська й істоти всіх видів.]],
            [1794] = [[Коли над останнім днем їхньої праці спустилися сутінки, титани назвали материк Калімдором, «землею вічного зоряного світла».]],
        },
    },
    [1836] = {
        en = "The World Tree and the Emerald Dream",
        title = "Світове Дерево та Смарагдовий Сон",
        pages = {
            [1836] = [[Багато років нічні ельфи невтомно відбудовували все, що могли, на своїй давній батьківщині. Покинувши зруйновані храми й дороги заростати, вони звели нові домівки серед зелених дерев і затінених пагорбів біля підніжжя Гіджалу. Згодом дракони, що пережили Великий Розкол, вийшли зі своїх потайних осель.]],
            [1837] = [[Червона Алекстраза, зелена Ізера й бронзовий Ноздорму спустилися на тихі галявини друїдів і оглянули плоди праці нічних ельфів. Малфуріон, який став надзвичайно могутнім архідруїдом, привітав великих драконів і розповів їм про створення нової Криниці Вічності.]],
            [1838] = [[Великі дракони стривожилися від лихої звістки. Вони припустили, що доки Криниця існує, Легіон колись може повернутися й знову напасти на світ. Малфуріон і троє драконів уклали угоду оберігати Криницю й не дати слугам Палаючого Легіону знайти дорогу назад у світ.]],
            [1839] = [[Алекстраза Життєзв’язниця поклала один зачарований жолудь у саме серце Криниці Вічності. У могутній чарівній воді жолудь ожив і вигнався у велетенське дерево. Його коріння росло з вод Криниці, а зелена крона, здавалося, сягала самого небесного склепіння.]],
            [1840] = [[Величезне дерево мало навіки стати символом зв’язку нічних ельфів із природою, а його життєдайна сила з часом мала поширитися й зцілити решту світу. Нічні ельфи назвали своє Світове Дерево Нордрасілом, що їхньою мовою означало «вінець небес».]],
            [1841] = [[Ноздорму Позачасовий зачарував Світове Дерево. Доки воно стоїть, нічні ельфи не старітимуть і не зазнаватимуть недуг та хвороб.]],
            [1842] = [[Ізера Сновидиця теж зачарувала Світове Дерево, пов’язавши його зі своїм царством, ефірним виміром, відомим як Смарагдовий Сон. Цей неосяжний і мінливий світ духу існував поза межами матеріального світу. Звідти Ізера керувала ритмами природи й самим шляхом розвитку світу.]],
            [1843] = [[Друїди нічних ельфів, разом із самим Малфуріоном, були пов’язані зі Сном через Світове Дерево. За містичною угодою вони погодилися засинати на цілі століття, щоб їхні духи могли мандрувати нескінченними стежками Ізериного Сну. Хоч друїдів і гнітила думка про стільки років життя, відданих сну, вони самовіддано погодилися дотримуватися угоди з Ізерою.]],
        },
    },
    [1844] = {
        en = "Exile of the High Elves",
        title = "Вигнання вищих ельфів",
        pages = {
            [1844] = [[Минали століття. Нове суспільство нічних ельфів міцніло й поширювалося лісом, що дедалі зеленів. Ельфи назвали його Ясенедолом. Тут знову з’явилося й розплодилося чимало істот і народів, яких було багато до Великого Розколу, зокрема фурболґи та свинобрази. Під доброзичливою опікою друїдів нічні ельфи жили під зорями в небаченому мирі й спокої.]],
            [1845] = [[Та чимало вцілілих високородних утрачали спокій. Як перед ними Іллідан, вони тяжко переживали втрату жаданої магії. Їх спокушала думка знову черпати силу Криниці Вічності й тішитися чарами. Зухвалий і прямолінійний ватажок високородних Дат'Ремар почав прилюдно глузувати з друїдів. Він називав їх боягузами за те, що вони відмовлялися від магії, яка, на його думку, належала їм по праву.]],
            [1846] = [[Малфуріон і друїди відкинули доводи Дат'Ремара й попередили високородних, що будь-яке чаклування каратимуть смертю. Дат'Ремар і його послідовники зухвало спробували переконати друїдів скасувати закон і накликали на Ясенеділ страшну магічну бурю.]],
            [1847] = [[Друїди не змогли стратити стількох одноплемінників, тож вирішили вигнати нерозважливих високородних зі своїх земель. Дат'Ремар і його послідовники раділи, що нарешті позбудуться консервативної рідні. Вони сіли на спеціально збудовані кораблі й вийшли в море. Ніхто не знав, що чекає за водами бурхливої Круговерті, та всі прагнули заснувати власну батьківщину, де зможуть безкарно чаклувати.]],
            [1848] = [[Високородні, або квел'дораї, як колись нарекла їх Азшара, зрештою висадилися на східній землі, яку люди назвуть Лордероном. Вони задумали збудувати своє магічне королівство Квел'Талас і відкинули звичаї нічних ельфів, поклоніння місяцю та нічний спосіб життя. Відтоді вони шануватимуть сонце й називатимуться вищими ельфами.]],
        },
    },
    [1849] = {
        en = "The Sentinels and the Long Vigil",
        title = "Стражі та довга варта",
        pages = {
            [1849] = [[Коли непокірна рідня пішла, нічні ельфи знову взялися оберігати зачаровану батьківщину. Друїди відчули, що наближається пора їхнього довгого сну. Вони готувалися заснути, покинувши коханих і родини.]],
            [1850] = [[Тіранда, що стала верховною жрицею Елуни, просила коханого Малфуріона не покидати її заради Ізериного Смарагдового Сну. Але честь зобов’язувала Малфуріона ступити на мінливі стежки Сну. Він попрощався зі жрицею й заприсягнувся, що вони завжди будуть разом, доки лишатимуться вірні своєму коханню.]],
            [1851] = [[Лишившись захищати Калімдор від небезпек нового світу, Тіранда зібрала могутнє військо зі своїх сестер, нічних ельфійок. Безстрашні, добре вишколені воїнки, що присягнули боронити Калімдор, стали відомі як Стражі. Затінені ліси Ясенедолу вони воліли обходити самі, та в скрутну мить могли покликати багатьох союзників.]],
            [1852] = [[Напівбог Кенарій лишився неподалік, на Місячних галявинах гори Гіджал. Його сини, відомі як Хранителі Гаю, пильно стежили за нічними ельфами й регулярно допомагали Стражам зберігати мир. Навіть сором’язливі дочки Кенарія, дріади, дедалі частіше з’являлися на видноті.]],
            [1853] = [[Охорона Ясенедолу забирала весь час Тіранди, та без Малфуріона поруч вона знала мало радості. За довгі століття, поки друїди спали, її страх нового демонічного вторгнення зростав. Вона не могла позбутися тривожного відчуття, що десь за Великою Темрявою неба Палаючий Легіон досі ховається й задумує помсту нічним ельфам і світові Азероту.]],
        },
    },
    [1854] = {
        en = "The Founding of Quel'Thalas",
        title = "Заснування Кель'Таласа",
        pages = {
            [1854] = [[Вищі ельфи під проводом Дат'Ремара полишили Калімдор і кинули виклик бурям Круговерті. Їхні флоти багато довгих років блукали серед уламків світу, відкриваючи таємниці й загублені королівства. Дат'Ремар, який узяв ім’я Сонячний Блукач, тобто «той, хто ходить удень», шукав місця могутніх магічних потоків, щоб збудувати нову батьківщину для свого народу.]],
            [1855] = [[Його флот нарешті пристав до берегів королівства, яке люди згодом назвуть Лордероном. Пробившись углиб суходолу, вищі ельфи заснували поселення в тихому Тірісфальському переліссі. За кілька років багато з них почали божеволіти. Припускали, що під цією землею спить якесь зло, але чуток ніхто не довів. Вищі ельфи згорнули табір і рушили на північ, до іншого краю, багатого на магічні потоки.]],
            [1856] = [[Подорож суворою гірською землею Лордерона ставала дедалі небезпечнішою. Відрізані від життєдайної сили Криниці Вічності, ельфи хворіли від холоду й гинули з голоду. Найбільше їх непокоїло те, що вони втратили безсмертя й стали вразливими до негоди.]],
            [1857] = [[Вони також трохи змаліли на зріст, а шкіра втратила характерний фіолетовий колір. Попри труднощі, вищі ельфи зустріли чимало дивовижних істот, яких ніколи не бачили в Калімдорі. Вони побачили й племена первісних людей, що полювали в прадавніх лісах. Найстрашнішою загрозою виявилися ненажерливі й хитрі лісові тролі Зул'Амана.]],
            [1858] = [[Ці тролі зі шкірою кольору моху могли відрощувати втрачені кінцівки та зцілювати тяжкі рани, але виявилися лютим, жорстоким народом. Імперія Амані простягалася майже всім північним Лордероном, і тролі завзято не пускали непроханих чужинців за свої межі. Ельфи зненавиділи лютих тролів і вбивали їх, щойно бачили.]],
            [1859] = [[За багато довгих років вищі ельфи нарешті знайшли землю, схожу на Калімдор. У глибині північних лісів материка вони заснували королівство Квел'Талас і заприсяглися створити могутню імперію, перед якою зблідне імперія їхніх родичів калдораїв. Та невдовзі вони довідалися, що звели Квел'Талас на місці давнього трольського міста, яке тролі й досі вважали священним. Майже одразу тролі юрбами пішли на ельфійські поселення.]],
            [1860] = [[Уперті ельфи не хотіли віддавати нову землю. Вони застосували чари, опановані завдяки Криниці Вічності, й стримали лютих тролів. Під проводом Дат'Ремара вони розбили загони Амані, які переважали їх числом десять до одного. Деякі ельфи пам’ятали давні застереження калдораїв і боялися, що їхні чари можуть привернути увагу вигнаного Палаючого Легіону.]],
            [1861] = [[Тож вони вирішили сховати свої землі за захисною перепоною, яка все одно давала б їм чаклувати. У різних місцях довкола Квел'Таласа вони поставили монолітні рунні камені, що окреслили межі магічної перепони. Камені приховували ельфійські чари від небезпек з інших вимірів і водночас відлякували забобонні трольські загони.]],
            [1862] = [[Із плином часу Квел'Талас став осяйним пам’ятником праці й магічній майстерності вищих ельфів. Його прекрасні палаци зводили в тому самому стилі, що й давні зали Калімдору, але вписували їх у природні обриси землі. Квел'Талас став осяйним самоцвітом, який ельфи так давно мріяли створити.]],
            [1863] = [[Владу над Квел'Таласом перебрала Рада Срібномісяця, хоча династія Сонячних Блукачів зберегла частку політичної сили. До Ради ввійшли семеро найвидатніших володарів вищих ельфів. Вони дбали про безпеку земель і народу. За захисною перепоною вищі ельфи й далі нехтували давніми пересторогами калдораїв і відкрито вживали магію майже в усьому.]],
            [1864] = [[Майже чотири тисячі років вищі ельфи жили мирно й безпечно у відлюдному королівстві. Та мстиві тролі не змирилися з поразкою. У глухих лісах вони плели змови й чекали, поки побільшає їхніх бойових загонів. Нарешті могутнє трольське військо виринуло з тінистих лісів і знову взяло в облогу осяйні шпилі Квел'Таласа.]],
        },
    },
    [1876] = {
        en = "The Guardians of Tirisfal",
        title = "Вартівники Тірісфалю",
        pages = {
            [1876] = [[Коли тролів на півночі не стало, ельфи Квел'Таласа взялися відбудовувати славну батьківщину. Переможні війська Аратора повернулися додому, на південні землі Строма.]],
            [1877] = [[Людське суспільство Аратора росло й процвітало. Торадін боявся, що його королівство розпадеться, якщо надто розростеться, і наполягав, щоб Стром лишався центром імперії. Після багатьох мирних років зростання й торгівлі могутній Торадін помер від старості, і молоде покоління Аратора дістало волю поширити імперію за землі Строма.]],
            [1878] = [[Перші сто магів, яких ельфи навчили чаклувати, примножили свою силу й значно глибше вивчили таємне мистецтво плести закляття. Їх свого часу добирали за міцну волю та шляхетний дух. Вони завжди чаклували обачно й відповідально, та передали свої таємниці й силу молодшому поколінню, яке не знало тягот війни й не розуміло потреби стримувати себе.]],
            [1879] = [[Молоді чарівники почали вдаватися до магії заради власної вигоди, забувши про обов’язок перед ближніми.]],
            [1880] = [[Коли імперія зростала й заселяла нові землі, молоді чарівники подалися на південь. Вони боронили побратимів від диких істот своїми чарами й дали змогу зводити нові міста-держави серед диких земель. Та що дужчими ставали маги, то пихатішими й віддаленішими від решти суспільства вони робилися.]],
            [1881] = [[Друге араторське місто-державу, Даларан, заснували на північ від Строма. Чимало молодих чарівників покинули тісні рамки Строма й рушили до Даларана, де сподівалися вільніше вживати нових сил. Своїм умінням вони звели зачаровані шпилі Даларана й з насолодою віддалися навчанню.]],
            [1882] = [[Мешканці Даларана мирилися з дослідами чарівників і розвивали жваве господарство під захистом своїх оборонців-магів. Та що більше чарівників вправлялося у своєму мистецтві, то слабшала й рвалася тканина дійсності довкола міста.]],
            [1883] = [[Безтурботні чари даларанських магів заманили у світ лиховісних слуг Палаючого Легіону, вигнаних після загибелі Криниці Вічності. Ці відносно слабкі демони з’являлися поодинці, але посіяли чимало сум’яття й хаосу на вулицях Даларана.]],
            [1884] = [[Більшість зустрічей із демонами були поодинокі, і правителі-маґократи всіма силами приховували їх від людей. Вони посилали наймогутніших чарівників ловити невловимих демонів, та тим часто бракувало сил навіть проти одного слуги могутнього Легіону.]],
            [1885] = [[За кілька місяців забобонні селяни запідозрили, що правителі-чарівники приховують від них щось жахливе. Вулицями Даларана пішли чутки про повстання. Налякані мешканці ставили під сумнів наміри й діла магів, якими колись захоплювалися. Боячись, що селяни повстануть, а Стром виступить проти них, маґократи звернулися до єдиних, хто, на їхню думку, міг зрозуміти їхню біду, — до ельфів.]],
            [1886] = [[Довідавшись від маґократів про демонів у Даларані, ельфи швидко послали до людських земель наймогутніших чарівників. Ті вивчили потоки енергії в Даларані й докладно описали всі помічені прояви демонічної діяльності. Вони дійшли висновку, що, хоча на волі лише кілька демонів, сам Легіон лишатиметься страшною загрозою, доки люди чаклують.]],
            [1887] = [[Рада Срібномісяця, що правила ельфами Квел'Таласа, уклала таємну угоду з маґократами Даларана. Ельфи розповіли їм історію прадавнього Калімдору й Палаючого Легіону, небезпека від якого досі нависала над світом. Доки люди користуватимуться магією, їм доведеться захищати своїх мешканців від лихих слуг Легіону.]],
            [1888] = [[Маґократи запропонували наділити силою одного смертного поборника, щоб він вів нескінченну таємну війну проти Легіону. Більшість людей ніколи не мали довідатися про Вартівників і загрозу Легіону, щоб від страху й підозр не спалахнуло повстання. Ельфи погодилися й заснували таємне товариство, яке мало наглядати за обранням Вартівника й допомагати стримувати хаос у світі.]],
            [1889] = [[Повірники таємно збиралися в затіненому Тірісфальському переліссі, де вищі ельфи вперше оселилися в Лордероні. Тому таємний орден назвали Вартівниками Тірісфалю. Обраних смертних поборників наділяли неймовірною силою ельфійської й людської магії. Одночасно міг бути лише один Вартівник, та його сила була така велика, що він міг сам відбивати слуг Легіону, хоч би де вони з’явилися.]],
            [1890] = [[Сила Вартівника була така велика, що добирати можливих наступників дозволялося тільки Раді Тірісфалю. Коли Вартівник старів або втомлювався від таємної війни з хаосом, Рада обирала нового поборника й за суворо визначених умов урочисто передавала йому силу.]],
            [1891] = [[З покоління в покоління Вартівники захищали люд від невидимої загрози Палаючого Легіону на землях Аратора й Квел'Таласа. Аратор ріс і процвітав, а магія ширилася всією імперією. Тим часом Вартівники пильно стежили за кожною ознакою демонічної діяльності.]],
        },
    },
    [1898] = {
        en = "The Seven Kingdoms",
        title = "Сім королівств",
        pages = {
            [1898] = [[Стром лишався центром Аратора, та по всьому Лордерону, як і в Даларані, поставали нові міста-держави. Першими виникли Ґілнеас, Альтерак і Кул-Тірас. Хоч кожне мало власні звичаї й торгівлю, усі визнавали спільну владу Строма.]],
            [1899] = [[Під пильним наглядом ордену Тірісфалю Даларан став головним осередком навчання чарівників з усього краю. Даларанські маґократи заснували Кірін-Тор, орден, якому доручили описати й дослідити кожне закляття, кожну реліквію та кожен магічний предмет, відомий тоді людству.]],
            [1900] = [[Ґілнеас і Альтерак стали міцними союзниками Строма й зібрали могутні війська, які досліджували гірські землі Каз-Модана на півдні. Саме тоді люди вперше зустріли давній народ дворфів і відвідали їхнє підземне місто Залізогарт. Люди й дворфи поділилися багатьма таємницями ковальства й інженерії та виявили, що однаково люблять битися й розповідати історії.]],
            [1901] = [[Місто-держава Кул-Тірас, засноване на великому острові на південь від Лордерона, розбагатіло завдяки рибальству й мореплавству. З часом Кул-Тірас зібрав могутній флот торгових суден, які ходили по всіх відомих землях у пошуках заморських товарів для обміну та продажу. Та навіть поки господарство Аратора процвітало, найміцніші його опори почали розпадатися.]],
            [1902] = [[Згодом володарі Строма захотіли перенести маєтки з посушливого півдня до зелених північних земель Лордерона. Спадкоємці короля Торадіна, останні нащадки роду Араті, наполягали, що Стром не можна покидати, чим викликали невдоволення більшості мешканців, які теж прагнули звідти піти.]],
            [1903] = [[У пошуках чистоти й просвітлення на дикій півночі володарі Строма вирішили покинути давнє місто. Далеко на північ від Даларана вони збудували нове місто-державу й назвали його Лордероном. Звідти й пішла назва всього материка. Лордерон став місцем паломництва для вірян і прихистком для всіх, хто шукав внутрішнього миру й безпеки.]],
            [1904] = [[Нащадки Араті, які лишалися за обваленими мурами давнього Строма, вирішили рушити на південь, за скелясті гори Каз-Модана. За багато довгих сезонів їхня подорож скінчилася. Вони осіли на півночі материка, який назвуть Азеротом. У родючій долині вони заснували королівство Штормовій, що швидко стало самодостатньою силою.]],
            [1905] = [[Нечисленні воїни, які ще жили у Стромі, вирішили лишитися й стерегти давні мури міста. Стром утратив значення столиці імперії, та з нього виросла нова держава Стромварт. Хоч кожне місто-держава окремо процвітало, імперія Аратора фактично розпалася. Кожна держава плекала власні звичаї та вірування й дедалі більше віддалялася від інших. Мрія короля Торадіна про єдине людство нарешті згасла.]],
        },
    },
    [1932] = {
        en = "The Last Guardian",
        title = "Останній Хранитель",
        pages = {
            [1932] = [[Хранителька Еґвінн дужчала з роками й силою Тірісфалю значно продовжила своє життя. Наївно вважаючи, що здолала Сарґераса назавжди, вона майже дев’ятсот років захищала світ від посіпак демонічного короля. Та зрештою Рада Тірісфалю постановила, що строк її служби минув.]],
            [1933] = [[Рада наказала Еґвінн повернутися до Даларана, щоб обрати нового спадкоємця сили Хранителя. Та Еґвінн ніколи не довіряла Раді й вирішила обрати спадкоємця самостійно.]],
            [1934] = [[Горда Еґвінн задумала народити сина й передати йому свою силу. Вона не хотіла, щоб орден Тірісфалю керував її спадкоємцем, як намагався керувати нею. У південному королівстві Азероті вона знайшла того, кого вважала найкращим батьком для сина, вправного людського чарівника Ніеласа Арана.]],
            [1935] = [[Аран служив придворним чаклуном і радником короля Азероту. Еґвінн спокусила чарівника й зачала від нього сина. Природний Ніеласів хист до магії міцно вкоренився в ненародженій дитині й визначив трагічні кроки, які вона зробить згодом. У дитину вклали й силу Тірісфалю, та пробудитися вона мала лише тоді, коли хлопець змужніє.]],
            [1936] = [[Минув час, і Еґвінн народила сина у відлюдному гаю. Вона назвала хлопця Медівом, що мовою вищих ельфів означає «хранитель таємниць», і вірила, що він виросте наступним Хранителем. Та лихий дух Сарґераса, який ховався всередині неї, заволодів беззахисною дитиною ще в її лоні. Еґвінн і гадки не мала, що новим Хранителем світу вже заволодів його найлютіший ворог.]],
            [1937] = [[Певна, що немовля здорове, Еґвінн принесла малого Медіва до двору Азероту й лишила його на виховання смертному батькові та його людям. Сама вона пішла в пустку й приготувалася до того, що чекало після смерті. Медів виріс міцним хлопцем і навіть не здогадувався, яку силу успадкував від Тірісфалю.]],
            [1938] = [[Сарґерас чекав, коли проявиться сила юнака. У підлітковому віці Медів уже зажив слави в Азероті завдяки хисту до магії. Він часто вирушав на пригоди з двома друзями: Ллейном, принцом Азероту, та Андуїном Лотаром, одним з останніх нащадків роду Араті. Троє хлопців повсякчас пустували по всьому королівству, та люди їх любили.]],
            [1939] = [[Коли Медівові виповнилося чотирнадцять, космічна сила в ньому прокинулася й зіткнулася з духом Сарґераса, який причаївся в його душі. Медів упав у заціпеніння, що тривало багато років.]],
            [1940] = [[Опритомнівши, він довідався, що вже виріс, а його друзі Ллейн і Андуїн стали правителями Азероту. Він хотів надзвичайною новою силою боронити рідний край, та темний дух Сарґераса підступно спотворював його думки й почуття.]],
            [1941] = [[Сарґерас тріумфував у серці Медіва, яке дедалі темнішало. Він знав, що підготовка до другого вторгнення майже завершена й що останній Хранитель світу здійснить усі його задуми.]],
        },
    },
    [1942] = {
        en = "Kil'jaeden and the Shadow Pact",
        title = "Кіл'джеден і Тіньовий пакт",
        pages = {
            [1942] = [[Приблизно тоді, коли в Азероті народився Медів, Кіл'джеден-Обманщик похмуро розмірковував серед своїх послідовників у Круговерті Порожнечі. За наказом свого пана Сарґераса хитрий володар демонів готував друге вторгнення Палаючого Легіону в Азерот.]],
            [1943] = [[Цього разу він не допустить помилок. Кіл'джеден вирішив, що йому потрібна нова сила, яка ослабить оборону Азероту ще до того, як Легіон ступить на його землю. Якщо смертним народам, зокрема нічним ельфам і драконам, доведеться протистояти новій загрозі, то з початком справжнього вторгнення їм забракне сил на гідний опір.]],
            [1944] = [[Саме тоді Кіл'джеден відкрив зелений Дренор, що спокійно плив у Великій Позамежній Темряві. Тут жили орки, які трималися кланів і шаманських традицій, та мирні дренеї. Дренор був такий же прекрасний, як і неосяжний.]],
            [1945] = [[Шляхетні орочі клани ходили відкритими степами й полювали задля втіхи, а допитливі дренеї зводили прості міста серед високих урвищ і вершин. Кіл'джеден знав, що мешканці Дренора могли б добре прислужитися Палаючому Легіонові, якби їх належно спрямувати.]],
            [1946] = [[Із двох народів саме войовничі орки здавалися Кіл'джеденові вразливішими до згуби Легіону. Він поневолив старого шамана Нер'зула майже так само, як Сарґерас у давнину підкорив королеву Азшару. Через хитрого шамана демон поширив жагу бою й жорстокість серед орочих кланів.]],
            [1947] = [[Невдовзі народ, відданий духовним традиціям, став кровожерливим. Тоді Кіл'джеден закликав Нер'зула та його людей зробити останній крок, цілком віддатися війні й смерті. Але старий шаман відчув, що його народ навіки стане невільником ненависті, і якимось чином оперся наказові демона.]],
            [1948] = [[Роздратований опором Нер'зула, Кіл'джеден почав шукати іншого орка, який віддав би свій народ у руки Легіону. Хитрий володар демонів нарешті знайшов охочого учня, Нер'зулового честолюбного вихованця Ґул'дана. За цілковиту покору Кіл'джеден пообіцяв Ґул'данові невимовну силу.]],
            [1949] = [[Молодий орк завзято вивчав демонічну магію й став наймогутнішим смертним чорнокнижником в історії. Він навчав інших молодих орків арканічного мистецтва й прагнув викорінити шаманські традиції. Ґул'дан показав побратимам новий різновид магії, страшну силу, від якої віяло згубою.]],
            [1950] = [[Щоб міцніше тримати орків, Кіл'джеден допоміг Ґул'данові заснувати Тіньову Раду, таємну секту, що маніпулювала кланами й поширювала чорнокнижництво Дренором. Що більше орків удавалися до тієї магії, то більше темніли й в’янули мирні поля та струмки. Згодом неозорі степи, де орки жили поколіннями, висохли до голої червоної землі. Демонічна сила поволі вбивала світ.]],
        },
    },
    [1951] = {
        en = "Rise of the Horde",
        title = "Народження Орди",
        pages = {
            [1951] = [[Під таємною владою Ґул'дана й Тіньової Ради орки ставали дедалі агресивнішими. Вони збудували величезні арени, де відточували бойову вправність у смертельних двобоях. Тоді кілька вождів виступили проти згуби, яка ширилася серед їхнього народу.]],
            [1952] = [[Один із тих вождів, Дуротан із клану Морозних Вовків, застерігав орків, щоб вони не дали ненависті й люті поглинути себе. Та його слів ніхто не почув. Могутніші вожді, як-от Ґром Пеклокрик із клану Пісні Війни, виступили за нову добу війни й панування.]],
            [1953] = [[Кіл'джеден знав, що орочі клани майже готові, та хотів бути певним їхньої цілковитої відданості. Він таємно наказав Тіньовій Раді прикликати Маннорота Руйнівника, живе втілення люті й руйнування. Ґул'дан зібрав вождів кланів і переконав їх, що кров Маннорота зробить їх непереможними.]],
            [1954] = [[За Ґромом Пеклокриком кров випили всі вожді кланів, крім Дуротана, і тим прирекли себе на неволю в Палаючого Легіону. Наділені люттю Маннорота, вожді самі того не знаючи поневолили й одноплемінників, які нічого не підозрювали.]],
            [1955] = [[Охоплені проклятою жагою крові, орки шукали, на кого вилити лють. Відчувши, що настав час, Ґул'дан об’єднав ворогуючі клани в єдину нестримну Орду.]],
            [1956] = [[Знаючи, що Пеклокрик, Орґрім Молот Згуби та інші вожді змагатимуться за верховну владу, Ґул'дан поставив над новою Ордою воєвождя-маріонетку. Він обрав Чорнорука Руйнівника, особливо зіпсутого й жорстокого орочого воєводу. Під орудою Чорнорука Орда рушила випробувати сили на простих дренеях.]],
            [1957] = [[За кілька місяців Орда винищила майже всіх дренеїв, які жили на Дренорі. Лише жменька вцілілих змогла уникнути страшної люті орків. Сп’янілий від перемоги Ґул'дан тішився могутністю Орди. Однак знав, що без ворога, на якого можна піти війною, Орда пожере себе в нескінченних чварах, гнана нестримною жагою славної різанини.]],
            [1958] = [[Кіл'джеден зрозумів, що Орда нарешті готова. Орки стали наймогутнішою зброєю Палаючого Легіону. Хитрий демон доповів своєму панові, який чекав, і Сарґерас погодився, що нарешті настав час помсти.]],
        },
    },
    [1959] = {
        en = "The Dark Portal and the Fall of Stormwind",
        title = "Темний Портал і падіння Штормовію",
        pages = {
            [1959] = [[Коли Кіл'джеден готував Орду до вторгнення в Азерот, Медів і далі боровся із Сарґерасом за власну душу. Король Ллейн, шляхетний володар Штормовію, дедалі більше остерігався пітьми, що, здавалося, спотворювала дух його давнього друга.]],
            [1960] = [[Ллейн поділився тривогою з Андуїном Лотаром, останнім нащадком роду Араті, якого призначив своїм військовим заступником. Та жоден із них не міг уявити, до яких жахіть призведе повільне занурення Медіва в безумство.]],
            [1961] = [[Щоб остаточно схилити Ґул'дана на свій бік, Сарґерас пообіцяв наділити його великою силою, якщо той поведе Орду в Азерот. Через Медіва він сказав чорнокнижникові, що той стане живим богом, якщо знайде підводну гробницю, куди Хранителька Еґвінн майже тисячу років тому поклала понівечене тіло Сарґераса.]],
            [1962] = [[Ґул'дан погодився й вирішив, що після перемоги над мешканцями Азероту знайде легендарну гробницю й забере нагороду. Певний, що Орда послужить його задумам, Сарґерас наказав почати вторгнення.]],
            [1963] = [[Спільними зусиллями Медів і чорнокнижники Тіньової Ради відкрили міжвимірну браму, відому як Темний Портал. Він з’єднав Азерот із Дренором. Брама була така велика, що крізь неї могли пройти цілі війська. Ґул'дан послав орочих розвідників оглянути землі, які вони мали завоювати. Повернувшись, розвідники запевнили Раду, що Азерот готовий упасти їм до рук.]],
            [1964] = [[Дуротан і далі вважав, що згуба Ґул'дана знищить його народ, і знову виступив проти чорнокнижників. Хоробрий воїн казав, що вони нищать чистоту орочого духу й що нерозважливе вторгнення стане його народові на погибель. Ґул'дан не наважився вбити такого улюбленого героя й вигнав Дуротана та клан Морозних Вовків в найдальші закутки нового світу.]],
            [1965] = [[Слідом за вигнаними Морозними Вовками крізь портал пройшло лише кілька орочих кланів. Орки швидко облаштували опорний пункт у Чорних драгвах, темному болотистому краї далеко на схід від Штормовію. Щойно вони розійшлися досліджувати нову землю, як зіткнулися з людськими оборонцями Штормовію.]],
            [1966] = [[Сутички зазвичай швидко вщухали, та в них виразно виявилися сильні й слабкі сторони обох народів. Ллейн і Лотар так і не змогли з’ясувати, скільки було орків, і могли тільки гадати, з яким військом доведеться битися.]],
            [1967] = [[За кілька років більшість орочої Орди перейшла в Азерот, і Ґул'дан вирішив, що настав час головного удару проти людства. Орда всією своєю силою вдарила по Штормовію, який нічого не підозрював.]],
            [1968] = [[Поки війська Азероту й Орди билися по всьому королівству, внутрішні чвари виснажували обидві сторони. Ллейн зі зневагою вважав диких орків нездатними завоювати Азерот і лишався в столиці Штормовії. Сер Лотар, навпаки, переконався, що ударити треба в самому серці ворожих сил. Йому довелося вибирати між переконанням і вірністю королю.]],
            [1969] = [[Довірившись чуттю, Лотар штурмував Каражан, вежу-фортецю Медіва, за допомогою молодого учня чарівника Кадґара. Кадґар і Лотар здолали одержимого Хранителя й пересвідчилися, що саме з нього почалася війна.]],
            [1970] = [[Убивши тіло Медіва, Лотар і молодий учень мимохіть вигнали дух Сарґераса в безодню. Чистий, доброчесний дух самого Медіва також зберігся і ще багато років мандрував астральним виміром.]],
            [1971] = [[Хоч Медіва здолали, Орда й далі переважала оборонців Штормовію. Коли перемога Орди наблизилася, Орґрім Молот Згуби, один із найвидатніших орочих вождів, почав помічати, як згуба ширилася кланами відтоді, як вони жили на Дренорі.]],
            [1972] = [[Його давній товариш Дуротан повернувся з вигнання й знову застеріг його про зраду Ґул'дана. Ґул'дан не забарився з відплатою. Його вбивці вирізали Дуротана та його родину й лишили живим тільки немовля. Молот Згуби не знав, що людський офіцер Еделас Блекмур знайшов Дуротанового сина й забрав його в рабство. Колись цей малий орк стане найвидатнішим провідником свого народу.]],
            [1973] = [[Розлючений смертю Дуротана, Орґрім узявся звільнити Орду від демонічної згуби. Зрештою він убив зіпсуту маріонетку Ґул'дана, Чорнорука, і сам став воєвождем. Під його рішучим проводом невблаганна Орда нарешті взяла фортецю Штормовію в облогу.]],
            [1974] = [[Ллейн тяжко недооцінив силу Орди й безпорадно дивився, як його королівство падає під натиском зеленошкірих загарбників. Зрештою короля вбила одна з найвправніших убивць Тіньової Ради, напіворчиця Ґарона.]],
            [1975] = [[Повертаючись із Каражана, Лотар і його воїни сподівалися зупинити кровопролиття й урятувати колись славну батьківщину. Та вони спізнилися й застали улюблене королівство в димних руїнах. Ороча Орда й далі спустошувала довкілля й забрала навколишні землі собі. Змушені критися, Лотар і його товариші дали сувору присягу відвоювати свій край за будь-яку ціну.]],
        },
    },
    [1992] = {
        en = "The Invasion of Draenor",
        title = "Вторнення на Дренор",
        pages = {
            [1992] = [[Коли полум’я Другої війни вщухло, Альянс рішуче взявся стримувати орочу загрозу. На півдні Лордерона збудували кілька великих ізоляційних таборів для полонених орків. Їх пильнували паладини й бувалі солдати Альянсу, і табори цілком виправдали сподівання.]],
            [1993] = [[Полонені орки були напружені й рвалися знову до бою, та наглядачі таборів, якими керували зі старої фортеці-в’язниці Дарнгольд, зуміли вберегти мир і підтримувати лад.]],
            [1994] = [[Тим часом на пекельному Дренорі нове ороче військо готувалося вдарити по Альянсу, який нічого не підозрював. Нер'зул, колишній наставник Ґул'дана, зібрав решту орочих кланів під своїм темним прапором. Спираючись на клан Тіньового Місяця, старий шаман задумав відкрити на Дренорі кілька порталів, якими Орда дісталася б нових, незайманих світів.]],
            [1995] = [[Щоб живити нові портали, йому треба було кілька зачарованих реліквій з Азероту. Заради них Нер'зул знову відкрив Темний Портал і послав крізь нього своїх ненажерливих слуг.]],
            [1996] = [[Нова Орда під проводом бувалих вождів Ґрома Пеклокрика й Кілроґґа Мертвого Ока з клану Кривавої Очниці заскочила оборонців Альянсу зненацька й промчала краєм, сіючи руїну. Під точним проводом Нер'зула орки швидко зібрали потрібні реліквії й відступили до безпечнішого Дренора.]],
            [1997] = [[Переконаний, що орки готують нове вторгнення, король Лордерона Теренас зібрав найдовіреніших воєначальників. Він наказав генералові Тураліону й архімагові Кадґару повести військо крізь Темний Портал і раз і назавжди покласти край орочій загрозі. Війська Тураліона й Кадґара ввійшли на Дренор і не раз билися з кланами Нер'зула на спустошеному півострові Пекельного Вогню.]],
            [1998] = [[Навіть за допомоги вищої ельфійки Аллерії Вітрогін, дворфа Курдрана Дикого Молота й бувалого воїна Даната Тролебоя Кадґар не зміг завадити Нер'зулові відкрити портали в інші світи.]],
            [1999] = [[Нер'зул нарешті відкрив портали, та не передбачив страшної ціни. Величезна сила порталів почала рвати саму тканину Дренора. Поки військо Тураліона відчайдушно виборювало шлях додому, в Азерот, світ Дренора почав обвалюватися в себе. Зрозумівши, що божевільний задум Нер'зула прирече весь їхній народ, Ґром Пеклокрик і Кілроґґ Мертве Око зібрали решту орків і втекли до відносно безпечного Азероту.]],
            [2000] = [[На Дренорі Тураліон і Кадґар погодилися на найбільшу жертву й вирішили знищити Темний Портал зі свого боку. Це мало коштувати життя і їм, і їхнім супутникам, та вони знали, що тільки так Азерот виживе. Поки Пеклокрик і Мертве Око відчайдушно прорубувалися крізь людські лави до свободи, Темний Портал вибухнув за ними. Їм і решті орків в Азероті вже не було дороги назад.]],
            [2001] = [[Нер'зул і вірний йому клан Тіньового Місяця пройшли крізь найбільший із нових порталів, коли велетенські виверження вулканів почали розривати материки Дренора. Палаючі моря піднялися й захлюпали розбиту землю, і нарешті змучений світ поглинув велетенський нищівний вибух.]],
        },
    },
    [2002] = {
        en = "The Birth of the Lich King",
        title = "Народження Короля-ліча",
        pages = {
            [2002] = [[Нер'зул і його послідовники ввійшли до Круговерті Порожнечі, ефірного виміру, що сполучає всі світи, розсіяні у Великій Позамежній Темряві. На жаль, там на них уже чекали Кіл'джеден і його демони. Кіл'джеден заприсягнувся помститися Нер'зулові за горду непокору й повільно розірвав тіло старого шамана шматок за шматком.]],
            [2003] = [[Кіл'джеден зберіг дух шамана живим і неушкодженим, щоб Нер'зул болісно усвідомлював, як понівечили його тіло. Нер'зул благав демона відпустити його дух і дарувати смерть, та той похмуро відповів, що їхній давній Кривавий пакт досі чинний, і Нер'зул ще має прислужитися йому.]],
            [2004] = [[Орки не змогли завоювати світ для Палаючого Легіону, тож Кіл'джеден мусив створити нове військо, щоб посіяти хаос у королівствах Азероту. Нове військо мало уникнути дрібних суперечок і чвар, які занапастили Орду. Воно мало бути безжальним і цілковито відданим своїй меті. Цього разу Кіл'джеден не міг дозволити собі поразки.]],
            [2005] = [[Тримаючи безпорадний дух Нер'зула в стазисі, Кіл'джеден дав йому останній вибір: служити Легіонові або терпіти вічні муки. Нер'зул знову нерозважливо погодився на демонічну угоду. Його дух замкнули в спеціально обробленій брилі криги, твердої, наче алмаз, із найдальших закутків Круговерті Порожнечі.]],
            [2006] = [[Замкнений у крижаній скрині, Нер'зул відчув, як його свідомість розширилася вдесятитисяч разів. Хаотичні сили демона спотворили його й зробили примарною істотою незбагненної сили. Тієї миті орк, якого знали як Нер'зула, був знищений назавжди, і народився Король-Ліч.]],
            [2007] = [[Демонічні сили спотворили також вірних Нер'зулові лицарів смерті й послідовників із клану Тіньового Місяця. Лихих заклиначів розірвали й перетворили на кістяних лічів. Демони подбали, щоб навіть після смерті Нер'зулові слуги беззаперечно йому корилися.]],
            [2008] = [[Коли настав час, Кіл'джеден пояснив, заради чого створив Короля-Ліча. Нер'зул мав поширити Азеротом пошесть смерті й жаху, яка назавжди знищить людську цивілізацію. Усі, кого вб’є страшна пошесть, мали повстати невмерлими, а їхні духи навіки підкоряться залізній волі Нер'зула.]],
            [2009] = [[Кіл'джеден пообіцяв, що коли Нер'зул виконає темне завдання й винищить людство, то звільниться від прокляття й дістане нове, здорове тіло.]],
            [2010] = [[Нер'зул погоджувався і, здавалося, прагнув виконати свою роль, та Кіл'джеден далі сумнівався в його відданості. Безтілесний Король-Ліч, ув’язнений у кришталевій скрині, мав деякий час коритися, але демон знав, що пильнувати його доведеться й надалі. Тож Кіл'джеден покликав добірну демонічну варту, вампіричних володарів жаху, наказав їм наглядати за Нер'зулом і стежити, щоб той виконав страшне завдання.]],
            [2011] = [[Тіхондрій, наймогутніший і найхитріший із володарів жаху, з запалом узявся за справу. Його захоплювала страшна сила пошесті й те, скільки народів Король-Ліч міг би винищити.]],
        },
    },
    [2022] = {
        en = "Lethargy of the Orcs",
        title = "Апатія орків",
        pages = {
            [2022] = [[Місяці минали, і в ізоляційних таборах збирали дедалі більше полонених орків. Коли табори переповнилися, Альянсові довелося збудувати нові на рівнинах на південь від Альтерацьких гір. Щоб утримувати й забезпечувати щораз більшу кількість таборів, король Теренас обклав держави Альянсу новим податком.]],
            [2023] = [[Податок і дедалі гостріші політичні суперечки за кордони викликали повсюдне невдоволення. Здавалося, крихка угода, що об’єднала людські народи в найтемнішу годину, може розпастися будь-якої миті.]],
            [2024] = [[Серед політичного неспокою багато наглядачів почали помічати тривожну зміну в полонених орках. Ті значно рідше намагалися втекти з таборів чи навіть побитися між собою. Вони дедалі більше байдужіли й занепадали духом.]],
            [2025] = [[У це було важко повірити, та орки, яких колись вважали найагресивнішим народом Азероту, зовсім утратили волю до бою. Дивна апатія спантеличила очільників Альянсу й далі виснажувала орків, які швидко слабшали.]],
            [2026] = [[Дехто припускав, що загадкову апатію викликала дивна хвороба, якою заражалися тільки орки. Та архімаг Антонідас із Даларана висунув іншу здогадку. Вивчаючи небагато відомостей про орочу історію, він дізнався, що орки поколіннями жили під згубним впливом демонічної сили.]],
            [2027] = [[Він припустив, що ці сили спотворили орків іще до їхнього першого вторгнення в Азерот. Схоже, демони осквернили орочу кров, і завдяки цьому орки здобули неприродну силу, витривалість і жагу бою.]],
            [2028] = [[Антонідас гадав, що загальна апатія орків викликана відвиканням цілого народу від несталої магії чорнокнижників. Саме ті чари колись зробили орків грізними, кровожерними воїнами.]],
            [2029] = [[Хоч ознаки були виразні, Антонідас так і не знайшов ліків від цього стану. До того ж багато інших магів і кілька поважних очільників Альянсу вважали, що шукати зцілення для орків нерозважливо. Обміркувавши їхній загадковий стан, Антонідас дійшов висновку, що зцілення має бути духовним.]],
        },
    },
    [2030] = {
        en = "The New Horde",
        title = "Нова Орда",
        pages = {
            [2030] = [[Еделас Блекмур, головний наглядач ізоляційних таборів, наглядав за полоненими орками зі своєї фортеці-в’язниці Дарнгольд. Особливо його цікавив один орк, осиротіле немовля, яке він знайшов майже вісімнадцять років тому. Блекмур виростив малого як улюбленого раба й назвав Траллом. Він навчав орка тактики, філософії та бою. Тралла навіть вишколили як гладіатора. Весь цей час підлий наглядач прагнув зробити з нього зброю.]],
            [2031] = [[Попри суворе виховання, Тралл виріс міцним і кмітливим орком і в серці знав, що рабське життя йому не підходить. Змужнівши, він довідався про свій народ, якого ніколи не бачив: після поразки більшість орків замкнули в ізоляційних таборах. За чутками, вождь орків Молот Згуби втік із Лордерона й переховувався. Тільки один непідкорений клан ще діяв потай, уникаючи пильного ока Альянсу.]],
            [2032] = [[Винахідливий, хоч і недосвідчений Тралл вирішив утекти з фортеці Блекмура й вирушив шукати одноплемінників. У мандрах він навідався до ізоляційних таборів і побачив, що його колись могутній народ став дивно заляканим і байдужим. Так і не зустрівши гордих воїнів, на яких сподівався, Тралл пішов шукати останнього непереможеного орочого вождя, Ґрома Пеклокрика.]],
            [2033] = [[Люди невпинно полювали на Пеклокрика, та він зберіг незгасну волю Орди до бою. За підтримки самого лише відданого клану Пісні Війни він далі потай воював проти гнобителів свого багатостраждального народу. Якими б не були його зусилля, полонених орків розбудити від заціпеніння йому не вдалося. Натхнений ідеалами Пеклокрика, вразливий Тралл перейнявся долею Орди та її воїнськими звичаями.]],
            [2034] = [[Шукаючи правди про своє походження, Тралл подався на північ, до легендарного клану Морозних Вовків. Він довідався, що Ґул'дан вигнав клан іще на початку Першої війни. А ще він дізнався, що сам є сином і спадкоємцем орочого героя Дуротана, справжнього вождя Морозних Вовків, якого майже двадцять років тому вбили в пустці.]],
            [2035] = [[Під опікою поважного шамана Дрек'Тара Тралл вивчив прадавні шаманські звичаї свого народу, забуті за лихої влади Ґул'дана. З часом він став могутнім шаманом і посів належне йому місце вождя вигнаних Морозних Вовків. Наділений силою самих стихій і сповнений рішучості знайти своє призначення, Тралл вирушив звільняти полонені клани й зцілити свій народ від демонічної згуби.]],
            [2036] = [[У мандрах Тралл знайшов старого воєвождя Орґріма Молота Згуби, який довгі роки жив відлюдником. Молот Згуби, близький друг Траллового батька, вирішив піти за молодим далекоглядним орком і допомогти звільнити полонені клани. За підтримки багатьох бувалих вождів Тралл зрештою відродив Орду й допоміг своєму народові віднайти нову духовну опору.]],
            [2037] = [[На знак відродження народу Тралл повернувся до Блекмурової фортеці Дарнгольд. Він поклав край задумам колишнього пана, узявши ізоляційні табори в облогу. Перемога коштувала дорого: під час визволення одного з таборів Молот Згуби поліг у бою.]],
            [2038] = [[Тралл узяв легендарний бойовий молот Орґріма, вдягнув його чорні лати й став новим воєвождем Орди. У наступні місяці невелика, але запальна Орда Тралла розорила ізоляційні табори й зірвала найвдаліші спроби Альянсу перехитрити її. За підтримки найкращого друга й наставника Ґрома Пеклокрика Тралл зробив усе, щоб його народ більше ніколи не став невільником.]],
        },
    },
    [2068] = {
        en = "Sunwell - The Fall of Quel'Thalas",
        title = "Сонячний Колодязь — падіння Квел'Таласа",
        pages = {
            [2068] = [[Артас переміг усіх, кого тепер вважав ворогами, та його досі переслідував привид Кел'Тузада. Привид сказав Артасові, що для наступного кроку задуму Короля-Ліча його треба відродити. Заради цього Артас мав принести останки Кел'Тузада до містичного Сонячного Колодязя, схованого у вічному королівстві вищих ельфів Квел'Таласі.]],
            [2069] = [[Артас зі Скарою вдерся до Квел'Таласа й узяв в облогу ельфійські укріплення, які вже сипалися. Сильвана Вітрогін, генералка слідопитів Срібномісяця, хоробро билася, та Артас зрештою винищив військо вищих ельфів і пробився до Сонячного Колодязя. На жорстокий доказ своєї влади він підняв полеглу Сильвану як банші, прокляту на вічне нежиття в службі завойовникові Квел'Таласа.]],
            [2070] = [[Зрештою Артас занурив останки Кел'Тузада у священні води Сонячного Колодязя. Цим учинком він споганив могутні води Вічності, а Кел'Тузад відродився як ліч-чаклун. Ставши значно могутнішою істотою, Кел'Тузад пояснив наступний крок задуму Короля-Ліча.]],
            [2071] = [[Коли Артас і військо мертвих повернули на південь, у Квел'Таласі не лишилося жодного живого ельфа. Славної батьківщини вищих ельфів, що стояла понад дев’ять тисяч років, більше не було.]],
        },
    },
    [2072] = {
        en = "Archimonde's Return and the Flight to Kalimdor",
        title = "Повернення Архімонда і шлях до Калімдору",
        pages = {
            [2072] = [[Щойно Кел'Тузад відновився, Артас повів Скару на південь, до Даларана. Там ліч мав здобути могутню книгу заклять Медіва й прикликати Архімонда назад у світ. Відтоді Архімонд сам мав почати останнє вторгнення Легіону. Навіть чарівники Кірін-Тору не завадили війську Артаса викрасти книгу Медіва. Невдовзі Кел'Тузад мав усе потрібне для закляття.]],
            [2073] = [[За десять тисяч років могутній демон Архімонд із військом знову ступив на землю Азероту. Та Даларан не був кінцем їхнього шляху. За наказом самого Кіл'джедена Архімонд і його демони пішли за невмерлою Скарою до Калімдору, намірившись знищити Нордрасіл, Світове Дерево.]],
            [2074] = [[Посеред цього хаосу з’явився самотній загадковий пророк, який узявся спрямовувати смертні народи. Ним виявився сам Медів, останній Хранитель, який дивом повернувся з потойбіччя, щоб спокутувати колишні гріхи. Медів розповів Орді й Альянсові про небезпеки, що на них чекали, і закликав об’єднатися.]],
            [2075] = [[За покоління ненависті орки й люди так озлобилися, що не хотіли й слухати. Медів мусив діяти з кожним народом окремо. Пророцтвами й хитрощами він спрямував їх за море, до легендарного Калімдору. Невдовзі орки й люди зустріли давно приховану цивілізацію калдораїв.]],
            [2076] = [[Орки під проводом Тралла зазнали кількох невдач, мандруючи Степами Калімдору. Вони заприятелювали з Керном Криваве Копито та його могутніми воїнами-тауренами. Та чимало орків знову піддалися демонічній жазі крові, яка мучила їх роками. Навіть найкращий воєначальник Тралла, Ґром Пеклокрик, зрадив Орду, віддавшись найнижчим інстинктам.]],
            [2077] = [[Коли Пеклокрик і вірні воїни Пісні Війни йшли лісами Ясенедолу, вони зіткнулися з давніми Стражами нічних ельфів. Певний, що орки знову стали на стежку війни, напівбог Кенарій вийшов прогнати Пеклокрика й орків. Та Пеклокрик із загоном, охопленим надприродною ненавистю й люттю, зміг убити Кенарія й спотворити давній ліс.]],
            [2078] = [[Зрештою Пеклокрик повернув собі честь, допомігши Траллові здолати Маннорота, володаря демонів, який першим прокляв орків своєю кров’ю ненависті й люті. Зі смертю Маннорота криваве прокляття орків нарешті скінчилося.]],
            [2079] = [[Поки Медів переконував орків і людей у потребі союзу, нічні ельфи по-своєму потай боролися з Легіоном. Тіранда Шелест Вітру, безсмертна верховна жриця Стражів нічних ельфів, відчайдушно боронила ліси Ясенедолу від демонів і невмерлих. Зрозумівши, що їй потрібна допомога, Тіранда вирушила будити друїдів нічних ельфів від тисячолітнього сну.]],
            [2080] = [[Покликавши давнього коханого, Малфуріона Шаленство Бурі, Тіранда зміцнила оборону й відкинула Легіон. За допомогою Малфуріона сама природа повстала, щоб здолати Легіон і його союзників зі Скари.]],
            [2081] = [[Шукаючи інших сплячих друїдів, Малфуріон знайшов давню в’язницю-курган, у якій закував брата Іллідана. Певна, що той допоможе проти Легіону, Тіранда його звільнила. Якийсь час Іллідан справді допомагав, та зрештою пішов у власних справах.]],
            [2082] = [[Нічні ельфи зібралися із силами й билися з Палаючим Легіоном із похмурою рішучістю. Легіон ніколи не відмовлявся від Криниці Вічності, давнього джерела сили Світового Дерева й серця королівства нічних ельфів. Якби напад на Дерево вдався, демони розірвали б світ на шматки.]],
        },
    },
    [2083] = {
        en = "The Betrayer Ascendant",
        title = "Сходження Зрадника",
        pages = {
            [2083] = [[Коли Легіон вдерся до Ясенедолу, Іллідана звільнили з підземної в’язниці після десяти тисяч років неволі. Він намагався догодити товаришам, та невдовзі взявся за старе й поглинув силу могутньої чорнокнижницької реліквії, Черепа Ґул'дана.]],
            [2084] = [[Від цього Іллідан набув демонічних рис і незмірно більшої сили. Він також отримав частину давніх спогадів Ґул'дана, особливо про Гробницю Сарґераса, острівне підземелля, де, за чутками, лежать останки Темного Титана.]],
            [2085] = [[Переповнений силою й знову вільний мандрувати світом, Іллідан рушив шукати своє місце у великому ладі речей. Та його перестрів Кіл'джеден із пропозицією, від якої годі було відмовитися. Кіл'джедена розлютила поразка Архімонда на горі Гіджал, та він мав важливішу справу за помсту.]],
            [2086] = [[Відчувши, що його творіння, Король-Ліч, стає надто могутнім, щоб тримати його в покорі, Кіл'джеден наказав Ілліданові знищити Нер'зула й раз і назавжди покласти край невмерлій Скарі. За це Іллідан мав одержати невимовну силу й почесне місце серед уцілілих володарів Палаючого Легіону.]],
            [2087] = [[Іллідан погодився й одразу подався знищити Зледенілий трон, крижану кришталеву скриню, у якій мешкав дух Короля-Ліча. Він знав, що для цього потрібна могутня реліквія. Спираючись на знання зі спогадів Ґул'дана, Іллідан вирішив знайти Гробницю Сарґераса й забрати останки Темного Титана.]],
            [2088] = [[Він зажадав сплати давніх боргів високородних і виманив змієподібних наґів із темних підводних лігв. Під проводом хитрої відьми леді Вайш наґи допомогли Ілліданові дістатися Розколотих островів, де, за чутками, стояла Гробниця Сарґераса.]],
            [2089] = [[Щойно Іллідан вирушив із наґами, наглядачка Маєв Пісня Тіней почала на нього полювати. Вона стерегла Іллідана десять тисяч років і тішилася нагоді знову його схопити. Та Іллідан перехитрив Маєв та її Вартових і заволодів Оком Сарґераса. З могутнім Оком він подався до колишнього міста чарівників Даларана.]],
            [2090] = [[Скориставшись силою магічних потоків міста, Іллідан за допомогою Ока спрямував руйнівне закляття на Крижану Корону, цитадель Короля-Ліча в далекому Нортренді. Удар розбив оборону Короля-Ліча й розколов самий дах світу. В останню мить закляття зупинили, коли на допомогу Маєв прийшли брат Іллідана Малфуріон і жриця Тіранда.]],
            [2091] = [[Знаючи, що Кіл'джеден не зрадіє його невдачі зі Зледенілим троном, Іллідан утік до спустошеного виміру, відомого як Позамежжя. Це були останні рештки Дренора, колишньої батьківщини орків. Там він збирався перечекати гнів Кіл'джедена й обдумати наступні кроки.]],
            [2092] = [[Зупинивши Іллідана, Малфуріон і Тіранда повернулися додому, до лісів Ясенедолу, щоб стерегти свій народ. Маєв так легко не здалася. Вона пішла за Ілліданом у Позамежжя, сповнена рішучості притягти його до суду.]],
        },
    },
    [2104] = {
        en = "Old Hatreds - The Colonization of Kalimdor",
        title = "Стара ненависть — заселення Калімдору",
        pages = {
            [2104] = [[Смертні народи перемогли, та опинилися у світі, розбитому війною. Скара й Палаючий Легіон майже винищили цивілізації Лордерона й ледь не довершили своєї справи в Калімдорі. Треба було зцілити ліси, забути давні кривди й заселити нові землі. Війна глибоко поранила кожен народ, та вони самовіддано згуртувалися заради нового початку. Першим кроком стало непевне перемир’я Альянсу й Орди.]],
            [2105] = [[Тралл повів орків до Калімдору, де вони за допомогою побратимів-тауренів заснували нову батьківщину. Назвавши свій край Дуротаром на честь убитого батька Тралла, орки осіли, щоб відродити колись славне суспільство.]],
            [2106] = [[Коли демонічне прокляття скінчилося, грізне військо Орди перетворилося на вільний союз народів, які дбали про виживання й добробут. За підтримки шляхетних тауренів і кмітливих тролів Темного Списа Тралл і його орки сподівалися на нову мирну добу у власному краї.]],
            [2107] = [[Решта війська Альянсу під проводом Джайни Праудмур осіла на півдні Калімдору. Біля східного узбережжя Бруднолипкої трясовини вони збудували укріплене портове місто Терамор. Там люди та їхні союзники-дворфи вчилися виживати в краї, який завжди буде до них ворожим. Захисники Дуротару й Терамора дотримувалися хиткого перемир’я, та спокій поселень не міг тривати довго.]],
            [2108] = [[Мир між орками й людьми розбився, коли до Калімдору прибув величезний флот Альянсу. Могутній флот під орудою верховного адмірала Дейліна Праудмура, батька Джайни, покинув Лордерон ще до того, як Артас знищив королівство. Після довгих виснажливих місяців у морі адмірал Праудмур шукав уцілілих з Альянсу.]],
            [2109] = [[Армада Праудмура загрожувала миру в усьому краї. Славетний герой Другої війни і непримиренний ворог Орди, батько Джайни вирішив знищити Дуротар, перш ніж орки там закріпляться.]],
            [2110] = [[Верховний адмірал поставив Джайну перед страшним вибором: допомогти йому в бою проти орків і зрадити нових союзників чи виступити проти рідного батька, щоб зберегти крихкий мир, якого нарешті досягли Альянс і Орда. Після тяжких роздумів Джайна обрала мир і допомогла Траллові здолати знавіснілого батька.]],
            [2111] = [[На жаль, адмірал Праудмур загинув у бою, перш ніж Джайна встигла з ним помиритися чи довести, що орки більше не кровожерні чудовиська. За її вірність орки дозволили війську Джайни безпечно повернутися додому, до Терамора.]],
        },
    },
