        pages = { [2176] = "Орман Стромвартський\nПерший генерал-капітан Багряного Походу\nГромадянин Стромварта\nЗник біля підніжжя льодовика Крижаної Корони" },
    },
    [2177] = {
        en = "Valea Twinblades",
        title = "Валея Два Леза",
        pages = { [2177] = "Валея Два Леза\nВоїнка Багряного Походу\nГромадянка Альтераку\nВостаннє її бачили в глибині Східних Зачумлених земель" },
    },
    [2178] = {
        en = "Yana Bloodspear",
        title = "Яна Кровоспис",
        pages = { [2178] = "Яна Кровоспис\nДруга очільниця вбивць Багряного Походу\nГромадянка Даларана\nЗникла в Тірісфальському переліссі" },
    },
    [2191] = {
        en = "The Twin Empires",
        title = "Імперії-близнюки",
        pages = {
            [2191] = [[Приблизно шістнадцять тисяч років тому, задовго до того, як нічні ельфи нерозважливо накликали гнів Палаючого Легіону, тролі правили більшою частиною Калімдору, тоді ще єдиного материка. Існували дві трольські імперії: імперія ґурубаші в південно-східних джунглях та імперія Амані в лісах у центрі материка.]],
            [2192] = [[Далеко на півночі, у краї, який нині звуть Нортрендом, жили менші племена. Вони заснували невелику державу Ґундрак, але так і не сягнули розмірів і достатку південних імперій.]],
            [2193] = [[Імперії ґурубаші й Амані не любили одна одну, та рідко воювали між собою. Тоді їхнім найбільшим спільним ворогом була третя імперія, цивілізація Азж'Акіру. Акіри, розумні комахоподібні істоти, правили землями далекого заходу. Вони були хитрі, неймовірно злі й невпинно розширювали володіння. Їх переслідувала думка винищити на землях Калімдору все живе, крім комах.]],
            [2194] = [[Тролі воювали з ними багато тисяч років, та так і не здобули справжньої перемоги. Зрештою завдяки завзяттю тролів царство акірів розкололося навпіл. Його мешканці втекли до окремих колоній на далекій півночі й півдні материка.]],
            [2195] = [[Постали два міста-держави акірів: Азжол-Неруб у північних пустках та Ан'Кіраж у південній пустелі. Тролі підозрювали, що під Калімдором є й інші колонії акірів, але ніхто їхнього існування не підтвердив.]],
            [2196] = [[Вигнавши комахоподібних, обидві трольські імперії повернулися до звичних справ. Попри велику перемогу, жодна не поширилася далеко за колишні межі. Проте давні тексти згадують невеликий гурт тролів, який відокремився від імперії Амані й заснував власну колонію в серці темного материка.]],
            [2197] = [[Там сміливі першопрохідці відкрили космічну Криницю Вічності, яка перетворила їх на істот надзвичайної сили. За деякими переказами, саме ці відважні тролі стали першими нічними ельфами, хоча такого припущення ніхто не довів.]],
        },
    },
    [2198] = {
        en = "Empires' Fall",
        title = "Падіння імперій",
        pages = {
            [2198] = [[Хоч походження нічних ельфів оповите таємницею, відомо, що вони піднеслися незабаром після відкриття Криниці Вічності. Попри спроби тролів стримати їх, нічні ельфи збудували могутню імперію, яка швидко поширилася прадавнім Калімдором. Застосувавши нищівні чари, яких забобонні тролі й уявити не могли, ельфи без особливих труднощів зробили те, чого злі акіри так і не змогли: повалили дві найбільші імперії світу.]],
            [2199] = [[Нічні ельфи послідовно руйнували оборону й шляхи постачання тролів. Тролі не могли протистояти нищівним чарам і впали під натиском. Нічні ельфи виявилися такими ж хитрими й кровожерливими, як і дикі тролі, чим накликали на себе їхню вічну ненависть і зневагу. Імперії ґурубаші й Амані розпалися всього за кілька років.]],
            [2200] = [[Зрештою нічні ельфи обпеклися об арканічний вогонь, яким намагалися керувати. Своїм нерозважливим чаклуванням вони принадили у світ демонічний Палаючий Легіон. Демони знищили значну частину їхньої цивілізації. Хоч немає записів про напади Легіону на будь-яку з трольських імперій, імовірно, битви точилися по всьому материку.]],
            [2201] = [[Наприкінці тієї жахливої війни, відомої як Війна Древніх, Криниця Вічності вибухнула всередину. Ударна хвиля розтрощила єдиний суходіл Калімдору. Центр материка пішов під море, лишивши тільки кілька окремих уламків суходолу.]],
            [2202] = [[Великі частини колишніх імперій Амані й ґурубаші досі лежать у землях Квел'Таласа й Тернистої долини відповідно. Царства Азж'Акіру, Азжол-Неруб і Ан'Кіраж, також уціліли, у нинішньому Нортренді й Танарісі відповідно. Обидва трольські народи оговтувалися від величезного спустошення прадавнього світу, який вони знали. Незламні тролі відбудували розорені міста й заходилися відновлювати колишню могутність.]],
        },
    },
    [2203] = {
        en = "Wrath of Soulflayer",
        title = "Гнів Здирача Душ",
        pages = {
            [2203] = [[Довгі століття після Великого Розколу світу далися тролям тяжко. У розбитих королівствах панували голод і жах. Тролі ґурубаші, доведені до відчаю, звернулися по допомогу до давніх містичних сил. Обидва трольські королівства однаково вірили у великий пантеон прадавніх богів, та ґурубаші підпали під владу найтемнішого з них.]],
            [2204] = [[Гаккар Здирач Душ, підлий і кровожерливий дух, почув поклик тролів і вирішив їм допомогти. Він відкрив ґурубаші таємниці крові й допоміг поширити їхню цивілізацію на більшу частину Тернистої долини та кілька островів Південних морів. Він дав їм велику силу, але жадав за свою допомогу дедалі більшої плати.]],
            [2205] = [[Кровожерний бог вимагав, щоб йому щодня приносили в жертву душі. Він мріяв увійти в матеріальний світ, щоб випити кров усіх смертних. Згодом ґурубаші збагнули, з ким зв’язалися, й обернулися проти нього. Найсильніші племена повстали проти Гаккара та його вірних жерців атал'ай.]],
            [2206] = [[Про страшну війну, яка спалахнула між послідовниками Гаккара й рештою племен ґурубаші, говорять лише пошепки. Молода імперія розбилася під чарами, які вивільнили розгніваний бог і його повсталі діти. Коли битва здавалася найбезнадійнішою, тролям удалося знищити втілення Гаккара й вигнати його зі світу.]],
            [2207] = [[Зрештою навіть його жерців атал'ай вигнали зі столиці Зул'Ґуруба, і їм довелося виживати в невідомих болотах на півночі. У затінених трясовинах вони звели великий храм поваленому богові, Атал'Гаккар, де могли й далі чинити волю свого пана…]],
            [2208] = [[Після великої громадянської війни, яка обернула їхні землі на руїни, решта племен ґурубаші розійшлася. Черепоколи, Криваві Скальпи й Темні Списи вирушили шукати власних земель у безкраїх джунглях Тернистої долини. Хоч над розбитою імперією запанував крихкий мир, дехто згадував пророцтво, що колись Гаккар наново народиться у світі й того дня проковтне його цілком.]],
        },
    },
    [2211] = {
        en = "Monument to Grom Hellscream",
        title = "Пам'ятник Ґрому Пеклокрику",
        pages = {
            [2211] = [[Тут спочиває Ґроммаш Пеклокрик, вождь клану Пісні Війни.

З Ґромом багато в чому почалося й скінчилося прокляття нашого народу. Його ім’я нашою давньою мовою означало «серце велетня». Він стократ виправдав це ім’я, коли сам-один виступив проти демона Маннорота й власною кров’ю здобув нам свободу.

Лок'тар оґар, старший брате. Хай Пісня Війни ніколи не змовкне.

Тралл, воєвождь Орди]],
        },
    },
    [2217] = {
        en = "Decorated Headstone",
        title = "Прикрашений надгробок",
        pages = { [2217] = "Світлій пам’яті Джессі Моралеса" },
    },
    [2291] = {
        en = "Archbishop Alonsus Faol",
        title = "Архієпископ Алонс Фаол",
        pages = {
            [2291] = [[Архієпископ Алонс Фаол
Щедрий покровитель Церкви Світла.

Архієпископ Фаол починав свої добрі справи в Стратгольмі, що в Лордероні, і був великим другом народу Штормовію. У темні дні після Другої війни він допоміг відновити братство Північнокраю й зібрав величезні кошти на відбудову самого міста.

Цей собор стоїть як оплот Святого Світла і як вічне свідчення шляхетності й щедрості однієї людини.]],
        },
    },
    [2292] = {
        en = "King Llane I of the House of Wrynn",
        title = "Король Ллейн I з роду Ріннів",
        pages = { [2292] = "Король Ллейн I з роду Ріннів\nВолодар Штормовію\nЗахисник Азероту" },
    },
    [2293] = {
        en = "Grand Admiral Daelin Proudmoore",
        title = "Верховний адмірал Дейлін Праудмур",
        pages = { [2293] = "Командувач флотів Альянсу\nДруг Штормовію" },
    },
    [2294] = {
        en = "Lady Mara Fordragon",
        title = "Леді Мара Фордраґон",
        pages = { [2294] = "Леді Мара Фордраґон\nВерховна служителька Світла Штормовію\nПокровителька біженців, які втекли до Лордерона після Першої війни.\nВона була світлою матір’ю нашого майбуття. Хай спочиває у Світлі." },
    },
    [2295] = {
        en = "Mists of Dawn",
        title = "Світанкові тумани",
        pages = {
            [2295] = [[Ще до Доби Пам’яті лагідна Мати-Земля дихнула на золоті світанкові тумани. Там, де осіли бурштинові хмари, простяглися безкраї поля, і на них хвилювалися пшениця та ячмінь. Ця долина була її творінням, великою житницею життя й надії.]],
            [2296] = [[Очі Матері-Землі сяяли над краєм, який вона своїм подихом покликала до життя. Її праве око, Ан'ше, сонце, давало землі світло й тепло. Її ліве око, Му'ша, місяць, давало спокій і сон створінням, що прокидалися на світанку. Така була сила її погляду, що з кожним поворотом небес Мати-Земля заплющувала одне зі своїх мрійливих очей. Так її люблячий погляд обернув день на ніч на першім світанку світу.]],
            [2297] = [[Поки праве око сяяло над золотим світанком, лагідні руки Матері-Землі простерлися над золотими рівнинами. Де проходила тінь її рук, із родючого ґрунту поставав шляхетний народ. Шу'гало, таурени, підвелися, щоб скласти подяку й молитву люблячій матері. Там, на безкраїх світанкових полях, діти землі присягнули її благодаті й заповіли благословляти її ім’я до останніх сутінків світу.]],
        },
    },
    [2298] = {
        en = "Sorrow of the Earthmother",
        title = "Скорбота Матері-Землі",
        pages = {
            [2298] = [[Діти землі блукали світанковими полями й прислухалися до темного шепоту з глибин світу. Шепіт навчав їх війни й обману. Багато шу'гало підпали під владу тіні й пішли шляхом злоби та підступу. Вони обернулися проти чистих серцем побратимів, а їхню невинність підхопив вітер над рівниною.]],
            [2299] = [[Серце Матері-Землі обважніло від лиха дітей. Вона не могла дивитися, як вони втрачають благодать. У горі вона вирвала очі й пустила їх кружляти безкраїм зоряним небом. Ан'ше й Му'ша прагнули втішити одне одного, та могли тільки гнатися за тьмяним сяйвом одне одного. Близнюки й досі женуться небом із кожним поворотом світу.]],
            [2300] = [[Зрячих очей у Матері-Землі вже не було, та довго лишатися осторонь світу свого серця вона не могла. Вона дослухалася до вітрів і чула все, що діялося на світанкових полях. Її велике серце завжди було з дітьми, а її любляча мудрість ніколи їх не полишала.]],
        },
    },
    [2301] = {
        en = "The White Stag and the Moon",
        title = "Білий олень та місяць",
        pages = {
            [2301] = [[У хоробрі серця своїх чистих дітей Мати-Земля вклала любов до полювання, бо створіння першого світанку були дикі й люті. Вони ховалися від Матері-Землі й шукали спокою в тіні та глухих закутках краю. Шу'гало полювали на цих звірів усюди, де могли їх знайти, і приборкували їх із благословення Матері-Землі.]],
            [2302] = [[Та один великий дух від них вислизав. Апа'ро, якого нічні ельфи знають як Малорна, був гордим оленем зі сніжно-білою шерстю. Його роги чіпляли небесне склепіння, а могутні копита вибивали глибини світу. Шу'гало гнали Апа'ро до краю світанкового світу й уже підступали, щоб спіймати гордого оленя.]],
            [2303] = [[Рятуючись від них, великий олень стрибнув у небо. Коли, здавалося, він уже втік, могутні роги заплуталися в зорях, які міцно його втримали. Хоч Апа'ро брикався й пручався, він не міг вирватися з небес. Тоді його й знайшла Му'ша, яка гналася за братом Ан'ше до світанку. Вона побачила, як могутній олень борсається, і відразу закохалася.]],
            [2304] = [[Хитра Му'ша уклала угоду з великим оленем: вона звільнить його із зоряних пут, якщо він покохає її й покладе край самотності. Му'ша покохала Апа'ро й зачала від нього дитину. Дитя, яке дехто назве напівбогом, народилося в затінених лісах ночі. Його зватимуть Кенарієм, і він ходитиме зоряною стежкою між світом пробуджених і небесним царством.]],
        },
    },
    [2305] = {
        en = "Forestlord and the first Druids",
        title = "Володар лісів і перші друїди",
        pages = {
            [2305] = [[Згодом дитя, Кенарій, виросло й стало таким самим величним, як його гордий батько. Брат і деревам, і зорям, великий мисливець блукав далекими краями світу й співав злагоджених пісень світанку. Усі істоти схилялися перед його грацією й красою. Хитрішого за сина місяця й білого оленя не було.]],
            [2306] = [[Зрештою Кенарій заприятелював із шу'гало й розповів їм про мінливий світ. Діти землі визнали його братом і присягнули допомагати йому дбати про поля життя й улюблені створіння великої Матері-Землі.]],
            [2307] = [[Кенарій навчив дітей землі говорити з деревами й рослинами. Шу'гало стали друїдами й чинили великі дива магії, щоб зцілити край. Багато поколінь шу'гало полювали разом із Кенарієм і вберігали світ від тіней, що ворушилися в його глибинах.]],
        },
    },
    [2308] = {
        en = "Hatred of the Centaur",
        title = "Ненависть кентаврів",
        pages = {
            [2308] = [[Коли світанкові тумани розвіялися й настала Доба Пам’яті, напівбог Кенарій рушив власним шляхом полями світу. Шу'гало, таурени, сумували за ним і забули чимало з друїдського мистецтва, якого він їх навчив. За кілька поколінь вони вже не пам’ятали, як говорити з деревами й дикими створіннями. І знову до їхніх вух долинув темний шепіт із глибин світу.]],
            [2309] = [[Хоч діти землі й не дослухалися до лихого шепоту, на їхні мандрівні племена впало страшне прокляття. Із чорних земель заходу прийшла орда вбивчих істот, кентаврів. Людожери й спустошники налетіли на шу'гало, наче пошесть. Хоробрі воїни й мисливці билися з благословенням Матері-Землі в серцях, та кентаврів здолати не вдалося.]],
            [2310] = [[Шу'гало мусили покинути землі предків і відтоді кочували безкраїми рівнинами. Вони вірили, що колись надія повернеться й розсіяні племена шу'гало знайдуть нову домівку під люблячими руками Матері-Землі.]],
        },
    },
