    [2731] = {
        en = "Rock of Durotan",
        title = "Скеля Дуротана",
        pages = {
            [2731] = [[Тут спочиває Дуротан, перший вождь клану Морозних Вовків й батько нашого шанованого воєвождя Тралла.

Він був найхоробрішим із нас. Його зрадили ті, хто хотів поневолити наш народ. Дуротан віддав життя, щоб ми здобули волю. Ми шануємо його й спадщину, яку він заповів нам через свого сина.

Дрек'Тар, ясновидець Морозних Вовків]],
        },
    },
    [2785] = {
        en = "Altar of Zanza",
        title = "Вівтар Занзи",
        pages = { [2785] = "Взиваємо до тебе, Занзо із Зулдазара. Благослови тих, хто просить твоєї допомоги, лоа Занзо. Благослови тих, хто хоче стати союзником зандаларського народу. Допоможи нам у скруті. Допоможи нам, лоа. Дай нам силу вразити ворогів. Дай нам силу ще раз перемогти бога крові." },
    },
    [2822] = {
        en = "Magical Ledger",
        title = "Чарівна облікова книга",
        pages = {
            [2822] = [[Як зробити арканітовий буй

Візьми трохи арканіту й трохи буя та змішай. Щасти!

Ти ж не думав, що буде так легко? Я досі винен тобі за ту відколоту луску, старий друже.

Азуреґос

P. S. Сподіваюся, ти збагнеш, як зробити справжній арканітовий буй, бо всю цю маячню я щойно вигадав. Гадки не маю, як вони знайдуть Пащу.]],
        },
    },
    [2828] = { en = "Crude Map", title = "Грубо накреслена мапа" },
    [2838] = {
        en = "From the Desk of Lord Victor Nefarius",
        title = "Лист лорда Віктора Нефарія",
        pages = {
            [2838] = [[Тому, кому це може бути цікаво,

Як же я люблю наші ігри! Якщо ви читаєте цього листа, то можу лише припустити, що якимсь дивом чи за волею богів вам удалося мене здолати. Безглуздо, знаю, але в історії цього світу бувало й дивніше.]],
            [2839] = [[Та, як і в усьому в житті, у цій сумній історії є світла сторона: розкішна трагедія, хаос і зло. Ви мене вбили, та робили це так повільно й безладно, що я встиг написати цього листа ПІСЛЯ того, як знищив вашу єдину надію врятувати світ. Усе, що лишилося від вашого уламка скіпетра, — червоний кришталевий пил.]],
            [2840] = [[Тіштеся обладунками Одвічної Відплати й Лютобура, які, може, знайдете в моїй скарбниці. Повірте, мені неабияк приємно знати, що я зміг зробити те, чого не зміг мій батько…

Щиро ваш,
лорд Віктор Нефарій
«Нефаріан»]],
        },
    },
